class Heap {
  constructor(cmp) {
    this.a = []
    this.cmp = cmp
  }
  get size() {
    return this.a.length
  }
  peek() {
    return this.a[0]
  }
  push(x) {
    const a = this.a
    a.push(x)
    let i = a.length - 1
    while (i > 0) {
      const p = (i - 1) >> 1
      if (this.cmp(a[i], a[p]) >= 0) break
      ;[a[i], a[p]] = [a[p], a[i]]
      i = p
    }
  }
  pop() {
    const a = this.a
    const top = a[0]
    const last = a.pop()
    if (a.length) {
      a[0] = last
      let i = 0
      for (;;) {
        const l = 2 * i + 1
        const r = l + 1
        let m = i
        if (l < a.length && this.cmp(a[l], a[m]) < 0) m = l
        if (r < a.length && this.cmp(a[r], a[m]) < 0) m = r
        if (m === i) break
        ;[a[i], a[m]] = [a[m], a[i]]
        i = m
      }
    }
    return top
  }
}

function maxCapital(k, funds, profits, costs) {
  const projects = costs.map((cost, i) => [cost, profits[i]]).sort((a, b) => a[0] - b[0])
  const ready = new Heap((a, b) => b - a)
  let i = 0
  for (let round = 0; round < k; round++) {
    while (i < projects.length && projects[i][0] <= funds) ready.push(projects[i++][1])
    if (!ready.size) break
    funds += ready.pop()
  }
  return funds
}

