import heapq

def max_capital(k, funds, profits, costs):
    projects = sorted(zip(costs, profits))
    ready, i = [], 0
    for _ in range(k):
        while i < len(projects) and projects[i][0] <= funds:
            heapq.heappush(ready, -projects[i][1])
            i += 1
        if not ready:
            break
        funds -= heapq.heappop(ready)
    return funds
